def tqft_oracle_level(d: int) -> tuple[int, int]:
    if d <= 3:
        return (0, 0)
    return (d - 3, d - 3)

def theory_spectrum(tower):
    REQUIRED = {'TQFT': 0, 'CFT': 1, 'String': 1, 'Gravity': 2}
    return {t for t, lvl in REQUIRED.items() if not tower.is_subsingleton(lvl)}

def min_stable_level(theories):
    REQUIRED = {'TQFT': 0, 'CFT': 1, 'String': 1, 'Gravity': 2}
    return max(REQUIRED[t] + 1 for t in theories) if theories else 0
